export function encode(numbers: number[]): number[] {
  const result: number[] = [];
  for (const num of numbers) {
    if (!isInteger(num) || num < 0 || num > 0xFFFFFFFF) {
      throw new Error('All numbers must be 32-bit unsigned integers');
    }
    let value = num;
    while (value > 0) {
      const byte = (value & 0x7F) | (result.length > 0 ? 0x80 : 0);
      result.push(byte);
      value >>= 7;
    }
  }
  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  for (let i = 0; i < bytes.length; i++) {
    let value = 0;
    let shift = 0;
    while (bytes[i] >= 0x80) {
      value = (value << 7) | (bytes[i] & 0x7F);
      i++;
    }
    value = (value << 7) | bytes[i];
    result.push(value);
  }
  return result;
}
